312	          <chakra.div __css={styles.compactButtonWrapper}>
313	            <ZimmButton
314	              label={compactGalleryButtonLabel}
315	              variant="primary"
316	              inverse
317	              onClick={onOpenGallery}
318	              sx={styles.galleryButton}
319	            />
320	          </chakra.div>
321	        )}
