72	  name,
73	  imageUrl,
74	  href,
75	  onClick,
76	  isSelected,
77	  isFocusable,
78	  posInSet,
79	  setSize,
80	  forceReload,
81	  variant = 'square',
82	}: ZimmColourSwatchProps) => {
83	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_RECIPE, { selected: isSelected, variant });
84	
85	  // The dynamic URL genuinely cannot live in the static recipe file, so this one dynamic `__css`
86	  // spread is the correct, deliberate exception — the same shape already used in
87	  // footer/footerNavColumn/index.tsx, an established pattern in this codebase.
88	  // backgroundImage is dynamic per swatch — cannot live in the static recipe file. The
89	  // data-image-url attribute is a test hook (element.style is not populated by emotion in JSDOM).
90	  const image = (
91	    <chakra.span __css={styles.image} style={{ backgroundImage: `url(${imageUrl})` }} data-image-url={imageUrl} />
92	  );
93	
94	  /*
95	   * Deliberately no `backgroundColor={name.toLowerCase()}` here, unlike base SFCC's own
96	   * `renderDefaultVariationAttribute` (product-view/index.jsx, and our own extraction of it in
97	   * product-view/index.tsx). Three reasons this stays out, permanently, not an oversight to
98	   * "fix" back in later:
99	   *   1. It uses the colour's display name as a raw CSS colour keyword — "Ivory" resolves as a
