137	      <ColourSwatchLink
138	        to={href}
139	        __css={styles.swatch}
140	        role="radio"
141	        aria-checked={isSelected}
142	        aria-label={name}
143	        aria-posinset={posInSet}
144	        aria-setsize={setSize}
